(function(){"use strict";var a=location.pathname.match(/\/attraction\/([^/]+)/);if(a){var c=a[1].replace(/\.html?$/,"");fetch("/data/related-guides.json",{cache:"no-store"}).then(function(e){return e.ok?e.json():{}}).catch(function(){return{}}).then(function(e){var i=e[c]||[];if(!i.length)return;var r=document.querySelector(".detail-main");if(!r||r.querySelector(".rg-section"))return;var o=document.createElement("style");o.textContent=".rg-section{margin-top:36px;}.rg-section h2{font-size:1.2rem;font-weight:800;margin:0 0 14px;}.rg-list{display:flex;flex-direction:column;gap:10px;}.rg-item{display:flex;align-items:center;gap:10px;padding:13px 16px;background:#f8fafc;border:1px solid var(--gray-100);border-radius:var(--radius);text-decoration:none;color:var(--gray-800);transition:all var(--dur);}.rg-item:hover{border-color:var(--brand);background:#fff;box-shadow:var(--shadow-sm);}.rg-item-icon{font-size:18px;}.rg-item-title{flex:1;font-size:14px;font-weight:600;}.rg-item-arrow{color:var(--brand);font-weight:700;}",document.head.appendChild(o);function s(t){return String(t).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}var n=document.createElement("div");n.className="rg-section",n.innerHTML='<h2>📖 相关攻略</h2><div class="rg-list">'+i.map(function(t){return'<a class="rg-item" href="'+t.url+'"><span class="rg-item-icon">📝</span><span class="rg-item-title">'+s(t.title)+'</span><span class="rg-item-arrow">→</span></a>'}).join("")+"</div>",r.appendChild(n)})}})();